const beginBeforeOrders=begin;begin=function(data){const positions=data.unitPositions?.map(p=>({...p})),orders=data.unitOrders?.map(o=>({...o}));const copy=JSON.parse(JSON.stringify(data));if(copy.map===undefined)copy.position={x:CAMP.x,y:CAMP.y+40};orderRestoreInProgress=true;try{beginBeforeOrders(copy)}finally{orderRestoreInProgress=false}if(positions)actors.forEach((a,i)=>{const p=positions[i];if(p&&walkable(p.x,p.y)){a.x=p.x;a.y=p.y;const order=orders?.[i];a.order=order||{kind:'hold'};if(order?.x!==undefined&&(order.kind==='move'||order.kind==='attackmove'))a.path=findPath(a,order)}});cam.x=clamp(active().x-VW/2,0,WW-VW);cam.y=clamp(active().y-VH/2,0,WH-VH);log=[];logMessage('诸界远征：独立地图、单控编队、百级转职与灵兽合体已启程。')};
const validateBeforeOrders=validateSave;validateSave=function(v){if(!validateBeforeOrders(v))return false;if(v.unitPositions!==undefined&&(!Array.isArray(v.unitPositions)||v.unitPositions.length!==5||v.unitPositions.some(p=>!p||!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>WW||p.y<0||p.y>WH)))return false;if(v.unitOrders!==undefined&&(!Array.isArray(v.unitOrders)||v.unitOrders.length!==5||v.unitOrders.some(o=>!o||!['hold','follow','move','attackmove'].includes(o.kind)||o.x!==undefined&&(!Number.isFinite(o.x)||!Number.isFinite(o.y)||o.x<0||o.x>WW||o.y<0||o.y>WH))))return false;return true};
