const updateBeforePets=update;update=function(dt){updateBeforePets(dt);if(!S||menu)return;if(currentMap()===0)$('#hint').textContent='营地 · 菜单→地图传送，或走近传送门按 F';for(const a of actors){a.petCd=Math.max(0,(a.petCd||0)-dt);a.petAnim=Math.max(0,(a.petAnim||0)-dt);if(a.petAnim<=0)a.petMode='idle';if(owned(a.i)&&petOf(a.i)&&a.hp>0&&a.order?.kind!=='move')petAbility(a.i,false)}for(const p of petFx)p.t-=dt;petFx=petFx.filter(p=>p.t>0).slice(-14);if(time>toastUntil)$('#realmToast').classList.remove('visible')};
const mountBeforeSanctuary=drawMount;drawMount=function(type,a,foreground=false){const mapped=PETS[type]?.art??type,anim=a.petAnim||0,mode=a.petMode;const pulse=anim>0?Math.sin(clamp(1-anim/1.25,0,1)*Math.PI):0,tilt=mode==='roar'?-pulse*.11:mode==='pounce'?pulse*.09:mode==='breath'?-pulse*.045:0,lunge=mode==='pounce'?pulse*14:0,rise=mode==='roar'?-pulse*8:0;g.save();g.translate(lunge,rise);g.rotate(tilt);if(type>=15)g.filter='hue-rotate('+((type-14)*32)+'deg)';const p=mountBeforeSanctuary(mapped,a,foreground);if(!foreground&&anim>0){const phase=Math.sin(clamp(1-anim/1.25,0,1)*Math.PI);g.save();g.translate(0,p.bob);g.strokeStyle=PETS[type].color;g.globalAlpha=.7*phase;g.lineWidth=2;if(mode==='roar'){for(let n=0;n<3;n++){g.beginPath();g.arc(58,-82,14+n*11+phase*18,-1.1,1.1);g.stroke()}}else if(mode==='pounce'){for(let n=0;n<3;n++)line(25+n*10,-55,55+n*10+phase*24,-22,PETS[type].color,2)}else{ellipse(55,-77,10+phase*7,7+phase*6,PETS[type].color+'bb');for(let j=0;j<4;j++)circle(55,-77,12+j*5+phase*10,PETS[type].color+'66',1)}g.restore()}g.restore();const sx=p.saddleX,sy=p.saddleY+p.bob;p.saddleX=sx*Math.cos(tilt)-sy*Math.sin(tilt)+lunge;p.saddleY=sx*Math.sin(tilt)+sy*Math.cos(tilt)+rise-p.bob;return p};
const warriorBeforeGems=drawWarrior;drawWarrior=function(a,mounted=false){const pose=warriorBeforeGems(a,mounted),gems=S?.heroes[a.i].gear[0]?.sockets?.filter(Boolean)||[];if(!gems.length||a.hp<=0)return pose;const level=Math.max(...gems.map(g=>g.level)),gem=gems.reduce((x,y)=>x.level>=y.level?x:y),color=GEMS[gem.type].color;g.save();g.translate(mounted?14:21,mounted?-36:-52);const attack=a.anim==='attack'&&a.animT>0;g.rotate(attack?Math.sin((1-a.animT/.44)*Math.PI)*1.6-.8:-.3);g.globalCompositeOperation='lighter';g.shadowColor=color;g.shadowBlur=6+level*3;g.globalAlpha=.65;line(0,9,0,-36,color,2+level*.75);line(-8,5,8,5,'#f9e7b0',2);line(0,9,0,19,'#ac8b64',3);line(0,-2,0,-35,'#fff6dc',1);if(level>=3)for(let j=0;j<level;j++){const ph=time*3+j*2.4;ellipse(Math.sin(ph)*9,-6-j*6,1.2+level*.25,2,color)}if(level>=5){g.strokeStyle=color;g.lineWidth=1.7;g.beginPath();g.moveTo(0,-36);for(let j=1;j<6;j++)g.lineTo(Math.sin(time*11+j)*10,-36+j*9);g.stroke()}if(attack&&level>=2){g.strokeStyle=color;g.lineWidth=level*1.2;g.beginPath();g.arc(0,-15,30+level*5,-2.2,.7);g.stroke()}g.restore();return pose};
function drawPetEffect(p){const progress=1-p.t/p.max;g.save();g.globalAlpha=Math.sin(progress*Math.PI)*.75;g.globalCompositeOperation='lighter';g.strokeStyle=p.color;g.fillStyle=p.color;g.lineWidth=3;if(p.kind==='roar'){for(let n=0;n<3;n++)circle(p.x,p.y,20+progress*75+n*17,p.color,2)}else if(p.kind==='breath'){const angle=Math.atan2(p.ty-p.y,p.tx-p.x),length=Math.min(360,Math.hypot(p.tx-p.x,p.ty-p.y));g.translate(p.x,p.y);g.rotate(angle);for(let j=0;j<22;j++){const u=(j/22+progress*.8)%1,x=u*length,y=Math.sin(j*2.1+progress*19)*(10+u*26);ellipse(x,y,7+u*15,3+u*8,j%3?p.color:'#ffe7ad')}line(0,0,length*.85,0,'#ffe5ac',4*(1-progress))}else if(p.kind==='pounce'){for(let j=0;j<3;j++)line(p.tx-28+j*18,p.ty-32+progress*20,p.tx-10+j*18,p.ty+23+progress*20,p.color,4)}else{for(let n=0;n<3;n++)ellipse(p.tx,p.ty,20+progress*115+n*14,10+progress*55+n*8,p.color+'55');circle(p.tx,p.ty,15+progress*95,p.color,2)}g.restore()}
